window.bookSummaryJSON = "<i>New York Times</i> best-selling author Christine Feehan's Dark Carpathian novels satisfy her fans' deepest yearnings with an irresistible concoction of suspense, sensuality, and the supernatural. Byron the Carpathian has traveled the globe for centuries, desperately seeking a mortal woman for his lifemate. And then, in an Italian villa, he hears the threads of enchanting music."; 
